   where:[['MINEDU — Directorio Nacional de CEBE','https://www.minedu.gob.pe/educacionbasicaespecial/pdf/cebe-prite/DIRECTORIO_CEBE.pdf','Rows where the UGEL is QUISPICANCHI.'],['INEI — Población con Discapacidad, 2017','https://www.inei.gob.pe/media/MenuRecursivo/publicaciones_digitales/Est/Lib1675/libro.pdf','Summary; p. 30 for Cusco.']],
